/**
 * Rain palettes for Valenced: generated by rain-themes tools/valenced_export.py. Do not edit.
 * https://github.com/alpine-vortex/rain-themes
 */

/// <reference types="@valenced/themes-api" />

import type { ThemeColors } from '@valenced/themes-api/types'
import data from './palettes.json'

type Roles = Record<string, string>

interface Palette {
	id: string
	name: string
	description: string
	light: string | null
	colors: { dark: Roles; light: Roles | null }
	raw: Record<string, string>
}

const tokens = data.tokens as Record<string, string[]>

function expand(roles: Roles) {
	const out: Record<string, string> = {}
	for (const [role, names] of Object.entries(tokens))
		for (const name of names) out[name] = roles[role]!
	return out
}

// Dark, Darker and Midnight get the palette; Light gets its official light flavour, or the dark one.
function colorsOf(p: Palette): ThemeColors {
	const dark = expand(p.colors.dark)
	const light = p.colors.light ? expand(p.colors.light) : dark
	return {
		semantic: { dark, darker: dark, midnight: dark, light },
		raw: { ...p.raw },
	}
}

function describe(p: Palette) {
	return p.light ? `${p.description} Light mode: ${p.light}.` : p.description
}

export default plugin({
	preInit({ themes }) {
		themes.registerGroup('rain', {
			name: 'Rain Themes',
			description: '21 palettes from rain-themes',
		})
		themes.registerGroup('rain-wallpaper', {
			name: 'Rain Themes with wallpaper',
			description: 'The same palettes over their matching wallpaper',
		})

		for (const p of data.palettes as Palette[]) {
			themes.registerTheme('rain', p.id, {
				name: p.name,
				description: describe(p),
				getColors: () => colorsOf(p),
			})
			themes.registerTheme('rain-wallpaper', p.id, {
				name: p.name,
				description: describe(p),
				getColors: () => colorsOf(p),
				background: { path: `assets/wallpapers/${p.id}.png` },
			})
		}
	},
})
